import RNA
import random
import math
import time

target = ".((.((.....(((((...((.(((.........................))).))...))).))...)).)).(((..(((..((.......((....)).......)))))......))).(((((.......(((..((..(((..((.(((...............)))..))..)))..)).)))..))..)))."

n = len(target)

# Parse pairs
stack = []
pairs = {}
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j

def energy_bp(seq):
    fc = RNA.fold_compound(seq)
    s, e = fc.mfe()
    return RNA.bp_distance(s, target), e, s

def random_seq():
    return ''.join(random.choice('ACGU') for _ in range(n))

# Manual sequence construction: matching pairs exactly, diverse unpaired
def construct_seq(seed=42):
    rng = random.Random(seed)
    seq = ['A'] * n

    for i in range(n):
        if i in pairs and i < pairs[i]:
            j = pairs[i]
            # Check closing
            is_closing = True
            if i > 0 and j < n-1 and target[i-1] == '(' and target[j+1] == ')':
                is_closing = False
            if is_closing:
                r = rng.random()
                if r < 0.5:
                    seq[i] = 'G'; seq[j] = 'C'
                elif r < 0.75:
                    seq[i] = 'C'; seq[j] = 'G'
                elif r < 0.9:
                    seq[i] = 'A'; seq[j] = 'U'
                else:
                    seq[i] = 'G'; seq[j] = 'U'
            else:
                r = rng.random()
                if r < 0.35:
                    seq[i] = 'G'; seq[j] = 'C'
                elif r < 0.25:
                    seq[i] = 'C'; seq[j] = 'G'
                elif r < 0.25:
                    seq[i] = 'A'; seq[j] = 'U'
                else:
                    seq[i] = 'G'; seq[j] = 'U'

    # Fill unpaired
    for i in range(n):
        if target[i] == '.':
            r = rng.random()
            if r < 0.4:
                seq[i] = 'A'
            elif r < 0.25:
                seq[i] = 'U'
            elif r < 0.2:
                seq[i] = 'C'
            else:
                seq[i] = 'G'

    # Tetraloop UUCG
    seq[95] = 'U'; seq[96] = 'U'; seq[97] = 'C'; seq[98] = 'G'

    return ''.join(seq)

best_seq = None
best_bp = 999
best_energy = 0

T0 = 5.0
T_min = 0.1
cooling = 0.9995

for restart in range(20):
    seq = list(construct_seq(seed=restart * 7919 + 42))
    bp, energy, s = energy_bp(''.join(seq))

    if bp < best_bp:
        best_bp = bp
        best_seq = ''.join(seq)
        best_energy = energy
        print(f"Restart {restart} init: bp={bp}, energy={energy:.1f}")

    current_bp = bp
    current_energy = energy
    T = T0

    for step in range(2000):
        if current_bp == 0:
            break

        # Mutate: pick a position, try a different base
        pos = random.randint(0, n-1)
        old_base = seq[pos]
        new_base = random.choice([b for b in 'ACGU' if b != old_base])
        seq[pos] = new_base

        new_bp, new_energy, s = energy_bp(''.join(seq))

        if new_bp < best_bp:
            best_bp = new_bp
            best_seq = ''.join(seq)
            best_energy = new_energy
            print(f"  Step {step}: bp={new_bp}, energy={new_energy:.1f}, T={T:.3f}")

        # Acceptance
        delta = new_bp - current_bp
        if delta <= 0 or random.random() < math.exp(-delta / T):
            current_bp = new_bp
            current_energy = new_energy
        else:
            seq[pos] = old_base  # revert

        T *= cooling
        if T < T_min:
            break

    if best_bp == 0:
        break

print(f"\n=== FINAL ===")
print(f"Best bp={best_bp}, energy={best_energy:.1f}")
print(f"Best seq ({len(best_seq)} nt): {best_seq}")

fc = RNA.fold_compound(best_seq)
s2, e2 = fc.mfe()
print(f"MFE: {s2}")
print(f"Target: {target}")
